/**
 * Transfer execution worker.
 *
 * Subscribes to approved transfer_intents in SpacetimeDB, executes Nessie,
 * then marks intents completed or failed via reducers.
 *
 * Prerequisites:
 *   spacetime start
 *   npm run spacetime:publish:local
 *   npm run spacetime:generate
 *   npm run worker:dev
 */

import { executeNessieTransfer } from './nessie-client.js';

// Generated by: npm run spacetime:generate
// eslint-disable-next-line import/no-unresolved
import { DbConnection, tables } from './module_bindings/index.js';

const SPACETIME_URI =
  process.env.SPACETIME_URI ?? 'ws://127.0.0.1:3000';
const DATABASE_NAME = process.env.SPACETIME_DATABASE ?? 'scamshield';
const TOKEN = process.env.SPACETIME_TOKEN;

const inFlight = new Set<string>();

type TransferRow = {
  id: bigint;
  userId: string;
  amountCents: bigint;
  destinationAccount: string;
  memo?: string;
  status: { tag: string };
};

type WorkerContext = {
  reducers: {
    completeTransfer: (args: {
      intentId: bigint;
      nessieTransferId: string;
    }) => void;
    failTransfer: (args: { intentId: bigint; reason: string }) => void;
  };
};

async function handleApprovedIntent(
  ctx: WorkerContext,
  row: TransferRow
) {
  if (row.status.tag !== 'Approved') return;

  const key = row.id.toString();
  if (inFlight.has(key)) return;
  inFlight.add(key);

  console.log(
    `[worker] Executing approved transfer ${key} for user ${row.userId}: $${Number(row.amountCents) / 100}`
  );

  const result = await executeNessieTransfer({
    intentId: row.id,
    userId: row.userId,
    amountCents: row.amountCents,
    destinationAccount: row.destinationAccount,
    memo: row.memo,
  });

  if (result.ok) {
    ctx.reducers.completeTransfer({
      intentId: row.id,
      nessieTransferId: result.transferId,
    });
    console.log(`[worker] Transfer ${key} completed (${result.transferId})`);
  } else {
    ctx.reducers.failTransfer({
      intentId: row.id,
      reason: result.error,
    });
    console.error(`[worker] Transfer ${key} failed: ${result.error}`);
  }

  inFlight.delete(key);
}

function registerHandlers(conn: InstanceType<typeof DbConnection>) {
  conn.db.transferIntent.onInsert((ctx, row) => {
    void handleApprovedIntent(ctx, row);
  });

  conn.db.transferIntent.onUpdate((ctx, _oldRow, row) => {
    void handleApprovedIntent(ctx, row);
  });
}

function connect() {
  const builder = DbConnection.builder()
    .withUri(SPACETIME_URI)
    .withDatabaseName(DATABASE_NAME)
    .onConnect(conn => {
      console.log(`[worker] Connected to SpacetimeDB (${DATABASE_NAME})`);
      registerHandlers(conn);

      conn.subscriptionBuilder().subscribe(
        tables.transferIntent.where(r => r.status.tag.eq('Approved'))
      );
    })
    .onConnectError((_ctx, err) => {
      console.error('[worker] Connection error:', err);
    })
    .onDisconnect(() => {
      console.warn('[worker] Disconnected — retrying in 3s');
      setTimeout(connect, 3000);
    });

  if (TOKEN) {
    builder.withToken(TOKEN);
  }

  builder.build();
}

console.log('[worker] ScamShield transfer worker starting…');
connect();
